217→/// Build a batch INSERT for `raw_transactions` with ON CONFLICT DO NOTHING.
218→pub fn build_raw_transaction_insert(
219→    txs: &[RawTransaction],
220→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
221→    let mut query = String::from(
222→        "INSERT INTO raw_transactions \
223→         (id, network, tx_hash, timestamp, block_number, raw_metadata, source, ingestion_run_id, ingested_at) \
224→         VALUES ",
225→    );
226→    let mut args = sqlx::postgres::PgArguments::default();
227→    for (i, tx) in txs.iter().enumerate() {
228→        let base = i * 9;
229→        if i > 0 {
230→            query.push_str(", ");
231→        }
232→        query.push_str(&format!(
233→            "(${}, ${}, ${}, ${}, ${}, ${}, ${}, ${}, ${})",
234→            base + 1,
235→            base + 2,
236→            base + 3,
237→            base + 4,
238→            base + 5,
239→            base + 6,
240→            base + 7,
241→            base + 8,
242→            base + 9,
243→        ));
244→        use sqlx::Arguments;
245→        args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
246→        args.add(&tx.network).map_err(|e| anyhow::anyhow!("{e}"))?;
247→        args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
248→        args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
249→        args.add(tx.block_number)
250→            .map_err(|e| anyhow::anyhow!("{e}"))?;
251→        args.add(&tx.raw_metadata)
252→            .map_err(|e| anyhow::anyhow!("{e}"))?;
253→        args.add(&tx.source).map_err(|e| anyhow::anyhow!("{e}"))?;
254→        args.add(tx.ingestion_run_id)
255→            .map_err(|e| anyhow::anyhow!("{e}"))?;
256→        args.add(tx.ingested_at)
257→            .map_err(|e| anyhow::anyhow!("{e}"))?;
258→    }
259→    query.push_str(" ON CONFLICT (network, tx_hash) DO NOTHING");
260→    Ok((query, args))
261→}
