        let txs: Vec<_> = (0..5).map(|_| make_raw_tx()).collect();
        let (query, _) = build_raw_transaction_insert(&txs).unwrap();
        // 5 rows * 9 params = 45 => highest param is $45
        assert!(query.contains("$45"));
        assert!(!query.contains("$46"));
    }

