        .bind(target_id)
        .fetch_all(self.pool())
        .await?;
        rows.iter().map(row_to_dataset_completeness).collect()
    }

    /// List all target completeness records for a given dataset name.
    pub async fn list_completeness_by_dataset(
        &self,
