    args.add(&dc.gap_ranges)
        .map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(&dc.notes).map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(dc.created_at)
        .map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(dc.updated_at)
        .map_err(|e| anyhow::anyhow!("{e}"))?;
    Ok((query, args))
}

